import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { formatCurrency, formatDate, ORDER_STATUS_COLORS, ORDER_STATUS_LABELS } from '../../utils/roles';

// Modal para seleccionar modificadores
const ModifierModal = ({ product, onClose, onAdd }) => {
  const [selectedModifiers, setSelectedModifiers] = useState({});
  const [itemNotes, setItemNotes] = useState('');

  if (!product) return null;

  const handleToggleOption = (modifierId, option) => {
    const modifier = product.modifiers?.find(m => m.id === modifierId);
    if (!modifier) return;

    setSelectedModifiers(prev => {
      const current = prev[modifierId] || [];
      const exists = current.find(c => c.id === option.id);

      if (exists) {
        // Quitar si ya está seleccionado
        return { ...prev, [modifierId]: current.filter(c => c.id !== option.id) };
      }

      // Verificar max_selections
      const max = modifier.max_selections || 1;
      if (current.length >= max) {
        // Reemplazar el primero si excede
        return { ...prev, [modifierId]: [...current.slice(1), option] };
      }

      return { ...prev, [modifierId]: [...current, option] };
    });
  };

  const isOptionSelected = (modifierId, optionId) => {
    return selectedModifiers[modifierId]?.some(o => o.id === optionId) || false;
  };

  const handleAdd = () => {
    // Convertir selectedModifiers a array plano
    const modifiersArray = [];
    Object.values(selectedModifiers).forEach(opts => {
      opts.forEach(opt => {
        modifiersArray.push({
          modifier_option_id: opt.id,
          quantity: 1,
        });
      });
    });

    onAdd(product, modifiersArray, itemNotes);
    onClose();
  };

  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
      background: 'rgba(0,0,0,0.8)', zIndex: 600,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      padding: 20,
    }} onClick={onClose}>
      <div className="card animate-fade-in" style={{
        maxWidth: 480, width: '100%', maxHeight: '80vh', overflowY: 'auto',
      }} onClick={e => e.stopPropagation()}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ color: '#e2e8f0' }}>⚙️ Personalizar: {product.name}</h3>
          <button onClick={onClose} style={{
            background: '#334155', color: '#e2e8f0', border: 'none',
            borderRadius: '50%', width: 32, height: 32, cursor: 'pointer',
          }}>✕</button>
        </div>

        <p style={{ color: '#fbbf24', fontWeight: 700, fontSize: 18, marginBottom: 16 }}>
          ${product.price?.toFixed(2)}
        </p>

        {/* Modificadores */}
        {product.modifiers?.map(modifier => (
          <div key={modifier.id} style={{ marginBottom: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <h4 style={{ color: '#94a3b8', fontSize: 13, textTransform: 'uppercase', letterSpacing: 1 }}>
                {modifier.name}
                {modifier.is_required && <span style={{ color: '#ef4444' }}> *</span>}
              </h4>
              <span style={{ color: '#64748b', fontSize: 11 }}>
                {modifier.min_selections > 0 ? `Mín ${modifier.min_selections}` : ''}
                {modifier.max_selections > 1 ? ` · Máx ${modifier.max_selections}` : ''}
              </span>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {modifier.options?.map(option => (
                <button
                  key={option.id}
                  onClick={() => handleToggleOption(modifier.id, option)}
                  style={{
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                    padding: '10px 14px', borderRadius: 8, border: '1px solid',
                    borderColor: isOptionSelected(modifier.id, option.id) ? '#38bdf8' : '#334155',
                    background: isOptionSelected(modifier.id, option.id) ? 'rgba(56, 189, 248, 0.1)' : '#0f172a',
                    color: isOptionSelected(modifier.id, option.id) ? '#38bdf8' : '#e2e8f0',
                    cursor: 'pointer', fontSize: 14,
                  }}
                >
                  <span>{option.name}</span>
                  <span style={{ color: option.price_adjustment > 0 ? '#fbbf24' : '#64748b', fontWeight: 600 }}>
                    {option.price_adjustment > 0 ? `+$${option.price_adjustment.toFixed(2)}` : option.price_adjustment < 0 ? `-$${Math.abs(option.price_adjustment).toFixed(2)}` : 'Incluido'}
                  </span>
                </button>
              ))}
            </div>
          </div>
        ))}

        {/* Notas */}
        <div style={{ marginBottom: 16 }}>
          <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Notas especiales</label>
          <input
            type="text"
            className="input"
            placeholder="Ej: sin cebolla, bien cocido, etc."
            value={itemNotes}
            onChange={e => setItemNotes(e.target.value)}
          />
        </div>

        <button onClick={handleAdd} className="btn btn-success" style={{ width: '100%', padding: 14 }}>
          ➕ Agregar al Pedido
        </button>
      </div>
    </div>
  );
};

const WaiterPage = () => {
  const [tables, setTables] = useState([]);
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [selectedTable, setSelectedTable] = useState(null);
  const [cart, setCart] = useState([]);
  const [orderType, setOrderType] = useState('dine_in');
  const [customerName, setCustomerName] = useState('');
  const [notes, setNotes] = useState('');
  const [activeTab, setActiveTab] = useState('new');
  const [myOrders, setMyOrders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [modifierModal, setModifierModal] = useState(null);
  const [activeCategory, setActiveCategory] = useState(null);

  useEffect(() => {
    fetchProducts();
    fetchMyOrders();
    fetchTables();
  }, []);

  const fetchTables = async () => {
    try {
      // Usar endpoint público o mock
      setTables([
        { id: 1, number: '01', name: 'Terraza 1', status: 'free', capacity: 4 },
        { id: 2, number: '02', name: 'Terraza 2', status: 'occupied', capacity: 4 },
        { id: 3, number: '03', name: 'Salón 1', status: 'free', capacity: 6 },
        { id: 4, number: '04', name: 'Salón 2', status: 'free', capacity: 6 },
        { id: 5, number: '05', name: 'VIP A', status: 'occupied', capacity: 8 },
      ]);
    } catch (e) {}
  };

  const fetchProducts = async () => {
    try {
      const res = await api.get('/menu/SUC-001');
      if (res.data.status) {
        const cats = res.data.data.categories;
        setCategories(cats);
        setActiveCategory(cats[0]?.id);
        const all = cats.flatMap(c => c.products);
        setProducts(all);
      }
    } catch (err) {
      console.error('Error cargando productos:', err);
    }
  };

  const fetchMyOrders = () => {
    api.get('/orders').then(res => {
      setMyOrders(res.data.data?.data || []);
    }).catch(() => {});
  };

  const handleAddProduct = (product) => {
    if (product.has_modifiers && product.modifiers?.length > 0) {
      setModifierModal(product);
    } else {
      addToCart(product, [], '');
    }
  };

  const addToCart = (product, modifiers, itemNotes) => {
    const existingIndex = cart.findIndex(item =>
      item.product_id === product.id &&
      JSON.stringify(item.modifiers) === JSON.stringify(modifiers)
    );

    if (existingIndex >= 0) {
      const newCart = [...cart];
      newCart[existingIndex].quantity += 1;
      if (itemNotes) newCart[existingIndex].notes = itemNotes;
      setCart(newCart);
    } else {
      setCart([...cart, {
        product_id: product.id,
        name: product.name,
        price: product.price,
        quantity: 1,
        notes: itemNotes || '',
        modifiers: modifiers || [],
      }]);
    }
  };

  const removeFromCart = (index) => {
    setCart(cart.filter((_, i) => i !== index));
  };

  const updateQuantity = (index, delta) => {
    setCart(cart.map((item, i) => {
      if (i === index) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const updateItemNotes = (index, note) => {
    setCart(cart.map((item, i) => i === index ? { ...item, notes: note } : item));
  };

  const submitOrder = async () => {
    if (cart.length === 0) return;
    setLoading(true);

    try {
      const items = cart.map(item => ({
        product_id: item.product_id,
        quantity: item.quantity,
        notes: item.notes || undefined,
        modifiers: item.modifiers.length > 0 ? item.modifiers : undefined,
      }));

      await api.post('/orders', {
        branch_id: 1,
        table_id: selectedTable?.id || null,
        customer_name: customerName || undefined,
        order_type: orderType,
        notes: notes || undefined,
        items,
      });

      setSuccess('¡Pedido enviado exitosamente!');
      setCart([]);
      setSelectedTable(null);
      setCustomerName('');
      setNotes('');
      fetchMyOrders();
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      alert(err.response?.data?.message || 'Error al enviar pedido');
    } finally {
      setLoading(false);
    }
  };

  const cartTotal = cart.reduce((sum, item) => {
    const modifiersTotal = item.modifiers?.reduce((mSum, m) => mSum + (m.price_adjustment || 0), 0) || 0;
    return sum + ((item.price + modifiersTotal) * item.quantity);
  }, 0);

  const activeCat = categories.find(c => c.id === activeCategory);

  return (
    <div>
      <h1 style={{ color: '#e2e8f0', marginBottom: 24, fontSize: 28 }}>📝 Toma de Pedidos</h1>

      <div style={{ display: 'flex', gap: 8, marginBottom: 24 }}>
        {[{ key: 'new', label: 'Nuevo Pedido', icon: '📝' }, { key: 'history', label: 'Mis Pedidos', icon: '📋' }].map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            style={{
              padding: '12px 24px', borderRadius: 10, border: 'none',
              background: activeTab === tab.key ? '#38bdf8' : '#1e293b',
              color: activeTab === tab.key ? '#0f172a' : '#94a3b8',
              fontWeight: 600, cursor: 'pointer', fontSize: 14,
            }}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {success && (
        <div style={{
          background: 'rgba(16, 185, 129, 0.1)', border: '1px solid #10b981',
          color: '#10b981', padding: 16, borderRadius: 10, marginBottom: 20,
        }}>
          {success}
        </div>
      )}

      {activeTab === 'new' ? (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 380px', gap: 24 }}>
          <div>
            <div className="card" style={{ marginBottom: 20 }}>
              <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'center' }}>
                <div>
                  <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Tipo de orden</label>
                  <select value={orderType} onChange={e => setOrderType(e.target.value)} className="input" style={{ width: 160 }}>
                    <option value="dine_in">🪑 Comer aquí</option>
                    <option value="takeout">📦 Para llevar</option>
                    <option value="delivery">🛵 Delivery</option>
                  </select>
                </div>
                {orderType === 'dine_in' && (
                  <div>
                    <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Mesa</label>
                    <select value={selectedTable?.id || ''} onChange={e => {
                      const t = tables.find(t => t.id === parseInt(e.target.value));
                      setSelectedTable(t || null);
                    }} className="input" style={{ width: 160 }}>
                      <option value="">Seleccionar...</option>
                      {tables.filter(t => t.status === 'free').map(t => (
                        <option key={t.id} value={t.id}>Mesa {t.number} — {t.name}</option>
                      ))}
                    </select>
                  </div>
                )}
                <div style={{ flex: 1, minWidth: 200 }}>
                  <label style={{ color: '#94a3b8', fontSize: 12, display: 'block', marginBottom: 6 }}>Cliente</label>
                  <input type="text" placeholder="Nombre del cliente (opcional)" className="input" value={customerName} onChange={e => setCustomerName(e.target.value)} />
                </div>
              </div>
            </div>

            {/* Categorías */}
            <div style={{ display: 'flex', gap: 8, marginBottom: 16, overflowX: 'auto' }}>
              {categories.map(cat => (
                <button
                  key={cat.id}
                  onClick={() => setActiveCategory(cat.id)}
                  style={{
                    padding: '8px 16px', borderRadius: 20, border: 'none',
                    background: activeCategory === cat.id ? '#38bdf8' : '#1e293b',
                    color: activeCategory === cat.id ? '#0f172a' : '#94a3b8',
                    fontWeight: 600, cursor: 'pointer', fontSize: 13, whiteSpace: 'nowrap',
                  }}
                >
                  {cat.icon} {cat.name}
                </button>
              ))}
            </div>

            {/* Productos */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 12 }}>
              {activeCat?.products?.map(product => (
                <div
                  key={product.id}
                  onClick={() => handleAddProduct(product)}
                  className="card"
                  style={{ cursor: 'pointer', padding: 16, transition: 'all 0.2s' }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = '#38bdf8'; e.currentTarget.style.transform = 'translateY(-2px)'; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = '#334155'; e.currentTarget.style.transform = 'translateY(0)'; }}
                >
                  <div style={{
                    width: '100%', height: 120, borderRadius: 10,
                    background: product.image_url ? `url(${product.image_url}) center/cover` : '#334155',
                    marginBottom: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 32,
                  }}>
                    {!product.image_url && '🍽️'}
                  </div>
                  <h4 style={{ color: '#e2e8f0', fontSize: 14, marginBottom: 4 }}>{product.name}</h4>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <p style={{ color: '#fbbf24', fontWeight: 700, fontSize: 16 }}>${product.price?.toFixed(2)}</p>
                    {product.has_modifiers && (
                      <span style={{ color: '#a855f7', fontSize: 11 }}>⚙️</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Carrito */}
          <div className="card" style={{ position: 'sticky', top: 24, height: 'fit-content' }}>
            <h3 style={{ color: '#e2e8f0', marginBottom: 16, fontSize: 18 }}>🛒 Pedido Actual</h3>

            {cart.length === 0 ? (
              <p style={{ color: '#64748b', textAlign: 'center', padding: 30 }}>Selecciona productos del menú</p>
            ) : (
              <>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12, marginBottom: 16, maxHeight: 400, overflowY: 'auto' }}>
                  {cart.map((item, index) => (
                    <div key={index} style={{ background: '#0f172a', borderRadius: 10, padding: 12 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                        <span style={{ color: '#e2e8f0', fontWeight: 600, fontSize: 14 }}>{item.name}</span>
                        <button onClick={() => removeFromCart(index)} style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: 16 }}>✕</button>
                      </div>
                      {item.modifiers?.length > 0 && (
                        <div style={{ marginBottom: 6 }}>
                          {item.modifiers.map((mod, mi) => (
                            <span key={mi} style={{ color: '#a855f7', fontSize: 11, marginRight: 6 }}>
                              + {mod.option_name || mod.modifier_option_id}
                            </span>
                          ))}
                        </div>
                      )}
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <button onClick={() => updateQuantity(index, -1)} style={{ width: 28, height: 28, borderRadius: 6, border: 'none', background: '#334155', color: '#e2e8f0', cursor: 'pointer', fontWeight: 'bold' }}>−</button>
                          <span style={{ color: '#e2e8f0', fontWeight: 600, minWidth: 20, textAlign: 'center' }}>{item.quantity}</span>
                          <button onClick={() => updateQuantity(index, 1)} style={{ width: 28, height: 28, borderRadius: 6, border: 'none', background: '#334155', color: '#e2e8f0', cursor: 'pointer', fontWeight: 'bold' }}>+</button>
                        </div>
                        <span style={{ color: '#fbbf24', fontWeight: 600 }}>
                          ${((item.price + (item.modifiers?.reduce((s, m) => s + (m.price_adjustment || 0), 0) || 0)) * item.quantity).toFixed(2)}
                        </span>
                      </div>
                      <input type="text" placeholder="Notas: sin cebolla, etc." className="input" style={{ fontSize: 12, padding: '8px 10px' }} value={item.notes} onChange={e => updateItemNotes(index, e.target.value)} />
                    </div>
                  ))}
                </div>

                <div style={{ borderTop: '1px solid #334155', paddingTop: 16, marginBottom: 16 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span style={{ color: '#e2e8f0', fontWeight: 700, fontSize: 16 }}>Total</span>
                    <span style={{ color: '#fbbf24', fontWeight: 700, fontSize: 18 }}>${cartTotal.toFixed(2)}</span>
                  </div>
                </div>

                <textarea placeholder="Notas generales del pedido..." className="input" style={{ marginBottom: 12, minHeight: 60, resize: 'vertical' }} value={notes} onChange={e => setNotes(e.target.value)} />

                <button onClick={submitOrder} className="btn btn-success" style={{ width: '100%', padding: 14, fontSize: 16 }} disabled={loading}>
                  {loading ? 'Enviando...' : '🚀 Enviar Pedido'}
                </button>
              </>
            )}
          </div>
        </div>
      ) : (
        <div>
          <h2 style={{ color: '#e2e8f0', marginBottom: 20 }}>📋 Mis Pedidos</h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {myOrders.map(order => (
              <div key={order.id} className="card animate-fade-in">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                  <div>
                    <span style={{ color: '#38bdf8', fontWeight: 700, fontSize: 16 }}>{order.order_number}</span>
                    <span style={{ color: '#64748b', marginLeft: 12, fontSize: 13 }}>{formatDate(order.created_at)}</span>
                  </div>
                  <span style={{
                    padding: '4px 12px', borderRadius: 20, fontSize: 12, fontWeight: 600,
                    background: ORDER_STATUS_COLORS[order.status] + '20',
                    color: ORDER_STATUS_COLORS[order.status],
                  }}>
                    {ORDER_STATUS_LABELS[order.status]}
                  </span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: '#94a3b8', fontSize: 14 }}>
                    {order.items?.length || 0} items · {order.order_type === 'dine_in' ? '🪑 Mesa' : '📦 ' + order.order_type}
                  </span>
                  <span style={{ color: '#fbbf24', fontWeight: 700, fontSize: 16 }}>{formatCurrency(order.total)}</span>
                </div>
              </div>
            ))}
            {myOrders.length === 0 && (
              <p style={{ color: '#64748b', textAlign: 'center', padding: 40 }}>No tienes pedidos registrados</p>
            )}
          </div>
        </div>
      )}

      {modifierModal && (
        <ModifierModal
          product={modifierModal}
          onClose={() => setModifierModal(null)}
          onAdd={addToCart}
        />
      )}
    </div>
  );
};

export default WaiterPage;
